162	public class ValidateSettings {
163	    private static final Pattern FIGURE = Pattern.compile("\\d{1,15}(\\.\\d{1,2})?");
164	    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
165	
166	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body)
167	            throws InvalidSettingException {
168	        boolean limitChanged = request != null && request.clerkLimit() != null;
169	        BigDecimal limit = null;
170	        if (limitChanged && !request.clerkLimit().trim().isEmpty()) {
171	            String value = request.clerkLimit().trim();
172	            if (!FIGURE.matcher(value).matches()) {
173	                throw new InvalidSettingException("A clerk limit is 0.00 or more, with up to two decimals");
174	            }
175	            limit = new BigDecimal(value).setScale(2);
176	        }
177	        BigDecimal floor = null;
178	        if (request != null && request.floor() != null) {
179	            String value = request.floor().trim();
180	            if (!FIGURE.matcher(value).matches()) {
181	                throw new InvalidSettingException("A floor is 0.00 or more, with up to two decimals");
182	            }
183	            floor = new BigDecimal(value).setScale(2);
184	        }
185	        Integer terms = null;
186	        if (request != null && request.terms() != null) {
187	            String value = request.terms().trim();
188	            if (!DAYS.matcher(value).matches()) {
189	                throw new InvalidSettingException("Terms are a whole number of days, 0 or more");
190	            }
191	            terms = Integer.valueOf(value);
192	        }
193	        body.set(new SettingsInput(limitChanged, limit, floor, terms));
194	    }
