204	/**
205	 * A claim's due figure, as the screen shows it: the due fixed when it was settled, else the figure
206	 * its person's last statement bound it to, else its live due: its amount times its grade's rate in
207	 * force on its date, divided by 100 and rounded half to even to two decimals, raised to the sheet's
208	 * floor when below it. Null for n/a (no floor applies to n/a).
209	 */
210	public final class ClaimFigure {
211	    private ClaimFigure() {}
212	
213	    public static BigDecimal of(Claim claim, List<Rate> rates, String grade, BigDecimal floor) {
214	        if (claim.getSettledDue() != null) return claim.getSettledDue();
215	        if (claim.isStated()) return claim.getStatedDue();
216	        return live(claim.getAmount(), rates, grade, claim.getDate(), floor);
217	    }
218	
219	    /** The amount at the grade's rate in force on the date, at least the floor; null with no such rate. */
220	    public static BigDecimal live(BigDecimal amount, List<Rate> rates, String grade, LocalDate date,
221	            BigDecimal floor) {
222	        return Rate.inForce(rates, grade, date)
223	                .map((pct) -> amount.multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
224	                .map((due) -> due.max(floor))
225	                .orElse(null);
226	    }
227	}
