326	/**
327	 * Settles the claim and fixes its due: its amount times its person's grade's rate in force on the
328	 * claim's date, divided by 100 and rounded half to even to two decimals, at least the sheet's floor. With no such rate the due is
329	 * not fixed. A claim a statement bound is settled at its bound figure. The user who opened the claim may not settle it.
330	 * A clerk (any user not made a steward) may settle it only when its due is at or below the sheet's
331	 * clerk limit; a due of n/a is within any limit.
332	 */
333	public class SettleClaim {
334	    public void apply(@Val Sheet sheet, @Val Claim claim, PersonRepository people, RateRepository rates,
335	            RoleRepository roles, SettingsRepository settingsStore, HttpServletRequest request)
336	            throws InvalidClaimStatusException, SelfSettleException, ClerkLimitException {
337	        claim.moveTo(ClaimStatus.SETTLED);
338	        String user = Audit.user(request);
339	        if (user.equals(claim.getOpenedBy())) throw new SelfSettleException(user);
340	        Person person = people.find(sheet.id(), claim.getPersonId());
341	        Settings settings = settingsStore.find(sheet.id());
342	        claim.setSettledDue(claim.isStated() ? claim.getStatedDue()
343	                : ClaimFigure.live(claim.getAmount(), rates.findAll(sheet.id()), person.getGrade(), claim.getDate(),
344	                        settings.floor()));
345	        if (!settings.withinClerkLimit(claim.getSettledDue()) && Role.CLERK.equals(roles.roleOf(sheet.id(), user))) {
346	            throw new ClerkLimitException(user, claim.getSettledDue(), settings.clerkLimit());
347	        }
348	    }
349	}
