374	import java.math.BigDecimal;
375	import java.time.LocalDate;
376	import java.util.ArrayList;
377	import java.util.LinkedHashMap;
378	import java.util.List;
379	import java.util.Map;
380	import net.officefloor.hq.app.claim.Claim;
381	import net.officefloor.hq.app.claim.ClaimFigure;
382	import net.officefloor.hq.app.claim.ClaimRepository;
