386	import net.officefloor.hq.app.rate.RateRepository;
387	
388	/**
389	 * The sheet's figures as the screen shows them: each person's claimed and due-total (by person id,
390	 * in the order they were added), and the sheet's claimed-total and due-total.
391	 */
392	public record Rollup(Map<Long, Figures> people, String claimedTotal, String dueTotal) {
393	
394	    /** A person's figures: their name, claimed and due-total (n/a when none). */
395	    public record Figures(String name, String claimed, String dueTotal) {
396	        boolean sameFigures(Figures other) {
397	            return other != null && claimed.equals(other.claimed) && dueTotal.equals(other.dueTotal);
398	        }
399	    }
400	
401	    /**
402	     * The sheet's figures now. A person's claimed is the amounts of their claims that count (OPEN
403	     * and SETTLED, but not OPEN while they are on hold) added up; their due-total the figures of those claims added up, skipping n/a (a live figure is at least the sheet's {@code floor}), and
404	     * n/a when their grade has no rate today and no claim that counts keeps a fixed figure. The
405	     * sheet's totals add these up, skipping n/a.
406	     */
407	    public static Rollup of(String sheetId, LocalDate today, PersonRepository people, ClaimRepository claims,
408	            RateRepository rates, BigDecimal floor) {
409	        List<Rate> all = rates.findAll(sheetId);
410	        List<Claim> sheetClaims = claims.findAll(sheetId);
411	        Map<Long, Figures> figures = new LinkedHashMap<>();
412	        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
413	        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
414	        for (Person person : people.findAll(sheetId)) {
415	            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
416	            BigDecimal due = BigDecimal.ZERO.setScale(2);
417	            boolean fixed = false;
418	            for (Claim claim : sheetClaims) {
419	                if (claim.getPersonId() != person.getId()) continue;
420	                if (!claim.counts(person.isHeld())) continue;
421	                claimed = claimed.add(claim.getAmount());
422	                if (claim.getSettledDue() != null || claim.getStatedDue() != null) fixed = true;
423	                BigDecimal figure = ClaimFigure.of(claim, all, person.getGrade(), floor);
424	                if (figure != null) due = due.add(figure);
425	            }
426	            boolean none = Rate.inForce(all, person.getGrade(), today).isEmpty() && !fixed;
427	            claimedTotal = claimedTotal.add(claimed);
428	            if (!none) dueTotal = dueTotal.add(due);
429	            figures.put(person.getId(), new Figures(person.getName(), show(claimed), none ? "n/a" : show(due)));
430	        }
431	        return new Rollup(figures, show(claimedTotal), show(dueTotal));
432	    }
433	
434	    /**
435	     * The audit lines for the move from {@code before} to this: one ROLLUP line per person whose
436	     * figures changed (a person new since counts as changed), then a TOTALS line when either of the
437	     * sheet's totals changed.
438	     */
439	    public List<String> changesSince(Rollup before, String sheetId, String user) {
440	        List<String> lines = new ArrayList<>();
441	        String head = " sheet=" + sheetId + " by=" + user;
442	        people.forEach((id, now) -> {
443	            if (!now.sameFigures(before.people().get(id))) {
444	                lines.add("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed()
445	                        + " due-total=" + now.dueTotal());
446	            }
447	        });
448	        if (!claimedTotal.equals(before.claimedTotal()) || !dueTotal.equals(before.dueTotal())) {
449	            lines.add("TOTALS" + head + " claimed-total=" + claimedTotal + " due-total=" + dueTotal);
450	        }
451	        return lines;
452	    }
453	
454	    private static String show(BigDecimal value) {
455	        return value.setScale(2).toPlainString();
456	    }
457	}
