518	/**
519	 * Takes the person's statement: their due-total now (the figures of their claims that count, added
520	 * up, skipping n/a; n/a when their grade has no rate today and no claim that counts keeps a fixed
521	 * figure), as the screen shows it. Every claim of theirs that counts is bound to its figure now (a live
522	 * one at least the sheet's floor);
523	 * every other claim of theirs is left unbound (live). The person's statement count goes up by one,
524	 * and the due-total and the sheet's today are kept as the last statement's.
525	 */
526	public class TakeStatement {
527	    public void take(@Val Sheet sheet, @Val Person person, ClaimRepository claims, RateRepository rates,
528	            SettingsRepository settings, PersonRepository people, Out<Statement> statementOut) {
529	        List<Rate> all = rates.findAll(sheet.id());
530	        BigDecimal floor = settings.find(sheet.id()).floor();
531	        BigDecimal total = BigDecimal.ZERO.setScale(2);
532	        boolean fixed = false;
533	        int counted = 0;
534	        for (Claim claim : claims.findByPerson(sheet.id(), person.getId())) {
535	            boolean counts = claim.counts(person.isHeld());
536	            if (counts) {
537	                counted++;
538	                if (claim.getSettledDue() != null || claim.getStatedDue() != null) fixed = true;
539	                BigDecimal figure = ClaimFigure.of(claim, all, person.getGrade(), floor);
540	                if (figure != null) total = total.add(figure);
541	                claim.bind(true, figure);
542	            } else {
543	                claim.bind(false, null);
544	            }
545	            claims.save(claim);
546	        }
547	        String dueTotal = Rate.inForce(all, person.getGrade(), sheet.today()).isEmpty() && !fixed
548	                ? "n/a" : total.toPlainString();
549	        person.setStatements(person.getStatementCount() + 1, dueTotal, sheet.today());
550	        people.saveStatements(person);
551	        statementOut.set(new Statement(dueTotal, counted));
552	    }
553	}
