565	/** The claims store, kept per sheet. */
566	@Repository
567	public class ClaimRepository {
568	
569	    private static final String COLUMNS = "id, sheet_id, person_id, amount, claim_date, note, status, claim_number, settled_due, opened_by, stated, stated_due";
570	
571	    private static final RowMapper<Claim> ROW = (rs, n) -> {
572	        Claim claim = new Claim(rs.getLong("id"),
573	            rs.getString("sheet_id"), rs.getLong("person_id"), rs.getBigDecimal("amount"),
574	            rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
575	            ClaimStatus.valueOf(rs.getString("status")),
576	            (Integer) rs.getObject("claim_number", Integer.class), rs.getBigDecimal("settled_due"),
577	            rs.getString("opened_by"));
578	        claim.bind(rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
579	        return claim;
580	    };
581	
582	    private final JdbcTemplate jdbc;
583	
584	    public ClaimRepository(JdbcTemplate jdbc) {
585	        this.jdbc = jdbc;
586	    }
587	
588	    /** The sheet's claims, newest first. */
589	    public List<Claim> findAll(String sheetId) {
590	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? ORDER BY id DESC",
591	                ROW, sheetId);
592	    }
593	
594	    /** The person's claims on the sheet, newest first. */
595	    public List<Claim> findByPerson(String sheetId, long personId) {
596	        return jdbc.query("SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC",
597	                ROW, sheetId, personId);
598	    }
599	
600	    /** The claim with this id on the sheet, or null when there is none. */
601	    public Claim find(String sheetId, long id) {
602	        List<Claim> found = jdbc.query(
603	                "SELECT " + COLUMNS + " FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id);
604	        return found.isEmpty() ? null : found.get(0);
605	    }
606	
607	    /**
608	     * Mark the claim OPEN in the store when it is still DRAFT there, holding its row until the
609	     * request commits so two opens of the same claim cannot both go through; false when another
610	     * request changed it first.
611	     */
612	    public boolean markOpened(Claim claim) {
613	        return jdbc.update("UPDATE claim SET status = 'OPEN' WHERE id = ? AND sheet_id = ? AND status = 'DRAFT'",
614	                claim.getId(), claim.getSheetId()) == 1;
615	    }
616	
617	    /**
618	     * The sheet's next claim number, taken in one statement so two claims opened at the same
619	     * moment never share a number; it is never given out again.
620	     */
621	    public int nextNumber(String sheetId) {
622	        return jdbc.queryForObject("SELECT last_claim_number FROM FINAL TABLE"
623	                + " (UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?)",
624	                Integer.class, sheetId);
625	    }
626	
627	    /** Insert a new claim (assigning its id) or update an existing one. */
628	    public void save(Claim claim) {
629	        if (claim.getId() != null) {
630	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, claim_number = ?, settled_due = ?, opened_by = ?, stated = ?, stated_due = ? WHERE id = ? AND sheet_id = ?",
631	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(),
632	                    claim.getStatus().name(), claim.getNumber(), claim.getSettledDue(), claim.getOpenedBy(),
633	                    claim.isStated(), claim.getStatedDue(), claim.getId(),
634	                    claim.getSheetId());
635	            return;
636	        }
637	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
638	        jdbc.update(con -> {
639	            PreparedStatement ps = con.prepareStatement(
640	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status) VALUES (?, ?, ?, ?, ?, ?)",
641	                    Statement.RETURN_GENERATED_KEYS);
642	            ps.setString(1, claim.getSheetId());
643	            ps.setLong(2, claim.getPersonId());
644	            ps.setBigDecimal(3, claim.getAmount());
645	            ps.setDate(4, Date.valueOf(claim.getDate()));
646	            ps.setString(5, claim.getNote());
647	            ps.setString(6, claim.getStatus().name());
648	            return ps;
649	        }, keys);
650	        claim.setId(keys.getKey().longValue());
651	    }
652	}
