package net.officefloor.hq.app.setting;

import java.math.BigDecimal;

/**
 * Validated settings, each scaled to two decimals: whether the clerk limit is changed and to what
 * (null: no limit), the floor (null: left as it is) and the terms in days (null: left as they are).
 */
public record SettingsInput(boolean clerkLimitChanged, BigDecimal clerkLimit, BigDecimal floor, Integer terms) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;

/**
 * A sheet's settings: its clerk limit, the highest due a clerk may settle (null: no limit), its
 * floor, the least a claim's live due may be, and its terms, the days after a claim's date that it
 * is due by.
 */
public record Settings(String sheetId, BigDecimal clerkLimit, BigDecimal floor, int terms) {
    /** A sheet's floor until it is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** A sheet's terms until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** Whether a due (null: n/a) is within the clerk limit. A due of n/a is within any limit. */
    public boolean withinClerkLimit(BigDecimal due) {
        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}
package net.officefloor.hq.app.setting;

import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The settings store: kept on the sheet's row. */
@Repository
public class SettingsRepository {

    private final JdbcTemplate jdbc;

    public SettingsRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Settings find(String sheetId) {
        List<Settings> found = jdbc.query("SELECT clerk_limit, due_floor, terms FROM sheet WHERE id = ?",
                (rs, n) -> new Settings(sheetId, rs.getBigDecimal("clerk_limit"), rs.getBigDecimal("due_floor"),
                        rs.getInt("terms")), sheetId);
        return found.isEmpty() ? new Settings(sheetId, null, Settings.DEFAULT_FLOOR, Settings.DEFAULT_TERMS) : found.get(0);
    }

    public void save(Settings settings) {
        jdbc.update("UPDATE sheet SET clerk_limit = ?, due_floor = ?, terms = ? WHERE id = ?",
                settings.clerkLimit(), settings.floor(), settings.terms(), settings.sheetId());
    }
}
package net.officefloor.hq.app.setting;

/**
 * Settings as the screen sends them, each only when it is being changed (null: left as it is): the
 * clerk limit, with up to two decimals (blank: no limit), the floor, with up to two decimals, and
 * the terms, a whole number of days.
 */
public record SettingsRequest(String clerkLimit, String floor, String terms) {
}
package net.officefloor.hq.app.setting;

/**
 * A sheet's settings, as the screen reads them: the clerk limit with two decimals ('' for none), the
 * floor with two decimals and the terms in days.
 */
public record SettingsResponse(String clerkLimit, String floor, String terms) {
    public static SettingsResponse from(Settings settings) {
        return new SettingsResponse(settings.clerkLimit() == null ? "" : settings.clerkLimit().toPlainString(),
                settings.floor().setScale(2).toPlainString(), Integer.toString(settings.terms()));
