test("late charge scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-10");
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00", "from": "2026-03-16"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "5.00", "from": "2026-03-16"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ada, {"grade": "B"})).toBe(true);
  const c_dot_0 = ui.must(await ui.quickAdd(pg_uma, {"name": "Dot", "amount": "12.50"}));
  const p_dot = await ui.personId(pg_uma, "Dot");
  expect(await ui.claimAction(pg_uma, c_dot_0, "void")).toBe(true);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.hold(pg_vic, p_ada, {})).toBe(true);
  await ui.setSetting(pg_vic, "clerk-limit", "");
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_dot).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("person-row-" + p_dot).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-due")).toHaveText("2.00");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-status")).toHaveText("VOID");
  await expect(pg_vic.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_vic.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_vic.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_vic.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  const c_ada_0 = ui.must(await ui.addClaim(pg_vic, p_ada, {"amount": "7.77", "date": "2026-02-10"}));
  expect(await ui.claimAction(pg_vic, c_ada_0, "open")).toBe(true);
  const c_dot_1 = ui.must(await ui.addClaim(pg_vic, p_dot, {"amount": "0.40", "date": "2026-02-25"}));
  await ui.setSetting(pg_vic, "floor", "3.00");
  expect(await ui.statement(pg_vic, p_cam)).toBe(true);
  expect(await ui.editClaim(pg_vic, c_dot_1, {"amount": "99.95"})).toBe(true);
  expect(await ui.statement(pg_vic, p_ada)).toBe(true);
  await ui.refresh(pg_vic);
  await expect(pg_vic.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
